update_rule.pseudocode:
if network_type == 'watts_strogatz':
    G = watts_strogatz_graph(n=population_size, k=network_mean_degree, p=rewiring_prob)
elif network_type == 'barabasi_albert':
    G = barabasi_albert_graph(n=population_size, m=preferential_attachment_m)
elif network_type == 'erdos_renyi':
    G = erdos_renyi_graph(n=population_size, p=erdos_renyi_p)
for each edge (u,v) in G:
    w ~ max(N(edge_weight_mean, edge_weight_std), 0.01)
    set edge weight w
for each node i:
    person[i].degree = degree(i)
return G and weights
